def result(status, code, message):
    return {"status": status, "code": code, "message": message}

def validate_edad(v):
    if v is None: return result("review","MISSING","Campo 'edad' ausente: envía un entero 0–120 o marca desconocido.")
    if not isinstance(v, int): return result("reject","BAD_TYPE",f"Campo 'edad' recibió {v!r}; se espera int.")
    if v < 0 or v > 120: return result("reject","OUT_OF_RANGE",f"Campo 'edad'={v} fuera de rango; usa 0–120.")
    if v < 18: return result("review","NEEDS_REVIEW",f"Campo 'edad'={v} corresponde a menor; revisa el registro.")
    return result("accept","OK","edad OK")

def validate_region(v):
    if v is None: return result("review","MISSING","Campo 'region' ausente: envía una región o marca desconocida.")
    if not isinstance(v, str): return result("reject","BAD_TYPE",f"Campo 'region' recibió {v!r}; se espera str.")
    if v not in ALLOWED_REGIONS: return result("review","NOT_IN_ALLOWLIST",f"Campo 'region'={v!r} no está en el catálogo; revisa la captura.")
    return result("accept","OK","region OK")

def validate_monto(v):
    if v is None: return result("review","MISSING","Campo 'monto_ingreso' ausente: envía un entero o marca desconocido.")
    if not isinstance(v, int): return result("reject","BAD_TYPE",f"Campo 'monto_ingreso' recibió {v!r}; se espera int.")
    if v < 0: return result("reject","OUT_OF_RANGE",f"Campo 'monto_ingreso'={v} negativo; usa ≥ 0.")
    if v > 50000: return result("review","NEEDS_REVIEW",f"Campo 'monto_ingreso'={v} supera 50000; revisa la captura.")
    return result("accept","OK","monto OK")

